// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    Reentrance c;
    Recorder r;

    function setUp() public { c = new Reentrance(); r = new Recorder(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount <= VALUE_CAP);
        vm.assume(amount > 0 && amount < 1e30);
        address actor = address(r);
        vm.deal(actor, amount);
        vm.prank(actor);
        c.addToBalance{value: amount}();
        assertEq(c.getBalance(actor), amount);

        vm.prank(actor);
        try c.withdrawBalance() {
            // The withdrawal must actually pay out the full balance to the caller:
            // the receiving contract must have recorded exactly `amount` arriving.
            assertTrue(r.received() == amount && address(c).balance == 0);
        } catch {
            assertTrue(false, "reference withdraw reverted");
        }
    }
}

contract Recorder {
    uint256 public received;
    receive() external payable { received += msg.value; }
}
